.sp-compact-module .pcard .d{max-width:58ch;margin:2px 0 0;font-size:.76rem;line-height:1.4;-webkit-line-clamp:3;}
.sp-compact-module .pcard .row{align-items:center;min-height:54px;margin-top:auto;padding-top:10px;gap:16px;}
.sp-compact-module .pcard .pr{font-size:.78rem;}
.sp-compact-module .pcard .add{min-height:44px;padding:8px 14px;font-size:.6rem;}
.sp-compact-module .pcard .g{font-size:.6rem;}
.sp-compact-module .pcard:focus-within{outline:2px solid var(--acc);outline-offset:3px;}
