.sp-opening .sp-head::after{margin:14px 0 0;}
.sp-opening .sp-flag{color:rgba(44,42,38,.68);font-size:.64rem;letter-spacing:.12em;margin-top:12px;}
/* The sampler is a range shelf: images, decision details, then one clear action. */
.sp-opening .sp-sampler{display:grid;grid-template-columns:minmax(235px,.72fr) minmax(280px,1fr) minmax(168px,auto);grid-template-areas:"packs details action";align-items:center;gap:20px;margin:0 0 8px;min-height:0;padding:17px 22px;border-color:rgba(69,119,152,.15);border-radius:8px;background:rgba(251,250,247,.74);box-shadow:0 6px 16px rgba(41,57,64,.045);}
.sp-opening .sp-sampler .minirow{grid-area:packs;display:flex;align-items:flex-end;justify-content:flex-start;flex:initial;gap:5px;width:100%;padding:6px 0;}
