@media(max-width:900px){
  .sp-opening{gap:16px;padding:34px 0 12px;}
  .sp-opening .sp-head{max-width:640px;padding:0;text-align:center;}
  .sp-opening .sp-head p{margin:0 auto;}
  .sp-opening .sp-head::after{margin:18px auto 0;}
  .sp-opening .sp-sampler{display:grid;grid-template-columns:minmax(0,1fr);grid-template-areas:"packs" "details" "action";gap:16px;margin:0 0 12px;padding:20px;text-align:center;}
  .sp-opening .sp-sampler .minirow{justify-content:center;width:min(100%,320px);margin:0 auto;}
  .sp-opening .sp-sampler .minirow img{max-width:48px;}
  .sp-opening .sp-sampler .pill{justify-self:center;width:min(100%,280px);}
  .sp .sp-range-nav{top:6px;padding:6px 0;}
  /* justify-content inherits `center` from the base .sp-cats rule. With
     flex-wrap:nowrap + overflow-x:auto a centred row spills BOTH directions and
     the leading overflow is unreachable, because scrollLeft cannot go negative.
     That hid the first category ("Bars") entirely at <=430px. flex-start is the
     baseline; `safe center` restores centring where supported, but only while
     the row actually fits. */
  .sp .sp-range-nav .sp-cats{display:flex;flex-wrap:nowrap;justify-content:flex-start;justify-content:safe center;width:calc(100% - 32px);min-height:54px;border-radius:18px;overflow-x:auto;scrollbar-width:none;-webkit-overflow-scrolling:touch;}
  .sp .sp-range-nav .sp-cats::-webkit-scrollbar{display:none;}
  .sp .sp-range-nav .sp-cats a{flex:0 0 auto;min-width:96px;min-height:54px;padding:6px 12px;font-size:.56rem;letter-spacing:.02em;line-height:1.08;}
