  .sp-tools{grid-template-columns:1fr;margin-top:10px;padding:14px 16px;}
  .catalogue-toolbar-heading{align-items:center;}
  .sort-tool,.view-tools{justify-content:flex-start;}
  .grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;}
  .pcard .row{align-items:stretch;flex-direction:column;}
  .pcard .add{width:100%;}
  .shop-list-view .pcard{grid-template-columns:1fr;}
}
@media(max-width:560px){
