      {n:'Goji Ripe Eclipse Bite',img:'eclipse_goji',d:'Medjool dates, almonds, cashews, coconut and goji berries in carob.',price:'$5.99–$59.99',size:'50g',sizes:ECLIPSE_SIZES,optionLabel:'Size'},
      {n:'Salted Caramel Fudge',img:'eclipse_fudge',d:'A rich fudgy texture with a satisfying crunch, finished with a generous indulgent slab of carob on top.',price:'$5.99–$59.99',size:'50g',sizes:ECLIPSE_SIZES,optionLabel:'Size'},
      {n:'Eclipse Bite Bundle',img:'eclipse_bundle',d:'All five Eclipse Bites together.',price:'$24.99',size:'5 x 50g'}
    ],
    /* Carob Bites are a SEPARATE category from Eclipse Bites. Copy and names lifted
