       weight is invented, size stays empty and the render guards the () span. */
    bites:[
      {n:'Goji Carob Bites',img:'bite_goji',d:'Small carob bites with a bright goji finish.',price:null,size:''},
      {n:'Coconut Carob Bites',img:'bite_coconut',d:'Coconut carob bites made for grazing.',price:null,size:''}
    ],
    elixirs:[
      {n:'Pure Carob Elixir',img:'elixir_plain',d:'A warm carob drink, naturally sweet and caffeine free.',price:'$23.95',size:'150g'},
