  };
  var DIET=['Vegan','GF','No Caffeine'];
  var PRICED={bars:true,elixirs:true,moons:true,eclipses:true,bites:false,bananas:true,powder:true};
  function amp(s){return s.replace(/&/g,'<span class="amp">&amp;</span>');}
  function flavourOf(p){
    var hay=(p.n+' '+p.d).toLowerCase();
    if(hay.indexOf('peppermint')>-1)return 'peppermint';
    if(hay.indexOf('hazelnut')>-1)return 'hazelnut';
    if(hay.indexOf('goji')>-1||hay.indexOf('coconut')>-1)return 'goji';
    if(hay.indexOf('cayenne')>-1||hay.indexOf('chilli')>-1)return 'cayenne';
    if(hay.indexOf('almond')>-1||hay.indexOf('salt')>-1)return 'almond';
    return 'pure';
  }
  Object.keys(CAT).forEach(function(cat){
    var grid=document.querySelector('.grid[data-cat="'+cat+'"]');if(!grid)return;
    CAT[cat].forEach(function(p,index){
      var priced=!!PRICED[cat] && !p.pending;
      var cardId='product-'+cat+'-'+index;
      var cleanName=p.n.replace(/"/g,'');
      var imageAttrs=(cat==='bites'||cat==='eclipses')?' loading="eager" decoding="async"':' loading="lazy" decoding="async"';
      var hasSizePicker=priced&&Array.isArray(p.sizes);
      var unitPrice=hasSizePicker?p.sizes[0].price:priceNumber(p.price);
      var unitQuantity=hasSizePicker?(p.sizes[0].quantity||1):1;
      /* the label mock-cart snapshots must stay true for EVERY option, so priced
         multi-option products show a range/from string, never one option's price. */
      var displayPrice=(cat==='moons'&&priced)?'From $2.50 each':((cat==='bananas'&&priced)?'From $2.99':p.price);
      var pickerLabel=p.optionLabel||'Size';
      var pickerAttribute=cat==='moons'?' data-tier-picker="moon"':' data-size-picker="eclipse"';
      var sizePicker=hasSizePicker?'<label class="size-picker"'+pickerAttribute+'><span>'+pickerLabel+'</span><select class="size-select" aria-label="'+pickerLabel+' for '+cleanName+'">'+p.sizes.map(function(option){return '<option value="'+option.price+'" data-quantity="'+(option.quantity||1)+'" data-label="'+option.label+'">'+option.label+' &middot; '+money(option.price)+'</option>';}).join('')+'</select></label>':'';
      /* Unpriced products still carry a sizes[] array, so without this the picker row
         collapses and the card renders a bare gap above the enquiry row. Fill that slot
         with an honest status line. NO price is surfaced: p.price is deliberately masked
         by pending:true and must stay masked. */
      if(!hasSizePicker&&!priced){
        sizePicker='<div class="size-picker is-made-to-order"><span>'+pickerLabel+'</span><span class="mto">Made to order</span></div>';
      }
      var el=document.createElement('article');el.className='pcard';el.setAttribute('aria-labelledby',cardId);
      el.dataset.cat=cat;el.dataset.flavour=flavourOf(p);el.dataset.name=p.n.toLowerCase();el.dataset.priced=priced?'1':'0';el.dataset.order=String(index);el.dataset.unitPrice=String(unitPrice);el.dataset.unitQuantity=String(unitQuantity);
      el.innerHTML='<div class="ph"><img src="'+PS+p.img+'.webp" alt="'+cleanName+'"'+imageAttrs+'></div>'+
        '<div class="tx"><h3 id="'+cardId+'">'+amp(p.n)+'</h3><div class="chips">'+DIET.map(function(c){return '<span>'+c+'</span>';}).join('')+'</div>'+
        '<p class="d">'+p.d+'</p>'+
        sizePicker+
        '<div class="row"><div class="price-wrap"><span class="pr'+(priced?'':' pending')+'"><span data-price-label>'+(priced?displayPrice:'Enquire for details')+'</span>'+(p.size?'<span class="g" data-size-note>('+p.size+')</span>':'')+'</span>'+(hasSizePicker?'<span class="sel-price" data-selected-price>Selected: '+money(unitPrice)+'</span>':'')+'</div><a class="add" aria-label="'+(priced?'Ask about ':'Enquire about ')+cleanName+'" href="mailto:info@maplemoon.com.au?subject=Enquiry%20about%20'+encodeURIComponent(p.n)+'">'+(priced?'Ask about this item':'Enquire')+'</a></div></div>';
      grid.appendChild(el);
    });
  });

  /* Selector -> price update. The .pr label is left on its range/"from" string so the
     snapshot mock-cart.js takes at load is true for every option; the live selected
     price rides in [data-selected-price] beside it. */
  function selectionOf(card){
    var sel=card&&card.querySelector('.size-select');
    if(!sel||!sel.options.length)return null;
    var opt=sel.options[sel.selectedIndex];
    return {price:Number(sel.value),quantity:Number(opt.dataset.quantity||1),label:opt.dataset.label||opt.textContent};
  }
  document.addEventListener('change',function(event){
    if(!event.target.matches||!event.target.matches('.size-select'))return;
    var card=event.target.closest('.pcard');if(!card)return;
    var pick=selectionOf(card);if(!pick)return;
    card.dataset.unitPrice=String(pick.price);
    card.dataset.unitQuantity=String(pick.quantity);
    var live=card.querySelector('[data-selected-price]');
    if(live)live.textContent='Selected: '+pick.label+' \u00b7 '+money(pick.price);
    /* Nate 14 Aug: the static (50g) was rendered for EVERY option, so Value pack read as
       $59.99 for 50g, about $1200/kg. No weight is authored here. If the chosen option is
       itself a weight we show that; otherwise the weight is hidden rather than guessed. */
    var note=card.querySelector('[data-size-note]');
    if(note){
      /* quantity is the real signal, not the label: option labels here are "1 moon" /
         "20 moons", never weights, so testing the label hid the weight permanently after
         any interaction. Unit weight is true at quantity 1 and meaningless above it. */
      if(!note.dataset.base) note.dataset.base=note.textContent;
      var single=Number(pick.quantity||1)===1;
      note.textContent=single?note.dataset.base:'';
      note.style.display=single?'':'none';
    }
    syncCartMeta();
  });
  /* Bridge: mock-cart.js snapshots each product once at load, so its cart lines cannot
     see a later selector change. Rather than fork the cart (which would break the
     candidate's focus trap / Escape behaviour), rewrite the rendered line meta in place
     from the card's current selection. mock-cart owns the dialog; this owns one string. */
  function syncCartMeta(){
    document.querySelectorAll('#mmCartDialog [data-mm-remove]').forEach(function(btn){
      var id=btn.dataset.mmRemove||'';
      var split=id.lastIndexOf('-');if(split<1)return;
      var card=document.querySelector('.pcard[data-cat="'+id.slice(0,split)+'"][data-order="'+id.slice(split+1)+'"]');
      if(!card)return;
      var pick=selectionOf(card);if(!pick)return;
      var article=btn.closest('article');if(!article)return;
      var meta=article.querySelector('.mm-cart-item-meta');if(!meta)return;
      var size=(card.querySelector('.pr .g')||{}).textContent||'';
      meta.textContent=[size.replace(/[()]/g,'').trim(),pick.label,money(pick.price)].filter(Boolean).join(' \u00b7 ');
    });
  }
  if('MutationObserver' in window){
    var bridgeTarget=document.body;
    new MutationObserver(function(){window.setTimeout(syncCartMeta,0);}).observe(bridgeTarget,{childList:true,subtree:true});
  }

  var state={flavour:'all',sort:'featured',view:'grid'};
  var cards=Array.prototype.slice.call(document.querySelectorAll('.pcard'));
  var status=document.getElementById('catalogue-status');
  var reset=document.getElementById('catalogue-reset');
  var flavourLabels={all:'all flavours',pure:'Pure',peppermint:'Peppermint',hazelnut:'Hazelnut',goji:'Coconut and Goji',cayenne:'Cayenne',almond:'Almond'};
  var sortLabels={featured:'featured order',name:'name',priced:'priced items first'};
  function syncQuery(){
    var url=new URL(window.location.href);
    if(state.flavour==='all')url.searchParams.delete('flavour');else url.searchParams.set('flavour',state.flavour);
    if(state.sort==='featured')url.searchParams.delete('sort');else url.searchParams.set('sort',state.sort);
    if(state.view==='grid')url.searchParams.delete('view');else url.searchParams.set('view',state.view);
    history.replaceState(null,'',url);
  }
  function applyState(){
    document.body.classList.toggle('shop-list-view',state.view==='list');
    cards.forEach(function(card){card.hidden=state.flavour!=='all'&&card.dataset.flavour!==state.flavour;});
    document.querySelectorAll('.grid').forEach(function(grid){
      var sorted=Array.prototype.slice.call(grid.children).sort(function(a,b){
        if(state.sort==='name')return a.dataset.name.localeCompare(b.dataset.name);
        if(state.sort==='priced')return b.dataset.priced.localeCompare(a.dataset.priced)||a.dataset.name.localeCompare(b.dataset.name);
        return Number(a.dataset.order)-Number(b.dataset.order);
      });
      sorted.forEach(function(card){grid.appendChild(card);});
    });
    document.querySelectorAll('.swatch').forEach(function(btn){var on=btn.dataset.flavour===state.flavour;btn.classList.toggle('is-active',on);btn.setAttribute('aria-pressed',on?'true':'false');});
    document.querySelectorAll('.view-btn').forEach(function(btn){var on=btn.dataset.view===state.view;btn.classList.toggle('is-active',on);btn.setAttribute('aria-pressed',on?'true':'false');});
    var select=document.getElementById('shop-sort');if(select)select.value=state.sort;
    var visible=cards.filter(function(card){return !card.hidden;});
    document.querySelectorAll('.sp-sec[id]').forEach(function(section){
      var hasMatch=Array.prototype.some.call(section.querySelectorAll('.pcard'),function(card){return !card.hidden;});
      section.hidden=state.flavour!=='all'&&!hasMatch;
      var navLink=document.querySelector('.sp-range-nav .sp-cats a[href="#'+section.id+'"]');
      if(navLink)navLink.hidden=state.flavour!=='all'&&!hasMatch;
    });
    var catNav=document.querySelector('.sp-range-nav .sp-cats');
    if(catNav)catNav.classList.toggle('is-filtered',state.flavour!=='all');
    if(status){
      var productWord=visible.length===1?'product':'products';
      var filterCopy=state.flavour==='all'?'across the full range':'for '+flavourLabels[state.flavour];
      status.textContent='Showing '+visible.length+' '+productWord+' '+filterCopy+', sorted by '+sortLabels[state.sort]+'.';
    }
    if(reset)reset.hidden=state.flavour==='all'&&state.sort==='featured'&&state.view==='grid';
    syncQuery();
  }
  var params=new URLSearchParams(window.location.search);
  var cvParam=params.get('compact-variant');
  /* SAT-SHOP-POLISH-R1: Variant F is now the DEFAULT presentation. No query string => F.
     QA override retained: ?compact-variant=f forces F on, any other value (e.g. ?compact-variant=off
     or bare ?compact-variant=) forces F off. */
  var selectedFRegular=(cvParam===null)?true:(cvParam==='f');
  if(selectedFRegular){
    document.body.classList.add('compact-variant-f');
    var selectedFBand=document.createElement('div');
    selectedFBand.className='wrap sp-compact-band';
    selectedFBand.setAttribute('aria-label','Compact secondary ranges');
    var selectedFSections=[
      {id:'elixirs',className:'sp-compact-elixirs'},
      {id:'bananas',className:'sp-compact-bananas'},
      {id:'powder',className:'sp-compact-powder'}
    ];
    var selectedFFirst=document.getElementById('elixirs');
    if(selectedFFirst)selectedFFirst.parentNode.insertBefore(selectedFBand,selectedFFirst);
    selectedFSections.forEach(function(item){
      var section=document.getElementById(item.id);
      if(!section)return;
      section.classList.remove('wrap');
      section.classList.add('sp-compact-module',item.className);
      var sectionGrid=section.querySelector('.grid');
      if(sectionGrid)sectionGrid.classList.add('compact-grid');
      selectedFBand.appendChild(section);
    });
  }
  if(['all','pure','peppermint','hazelnut','goji','cayenne','almond'].indexOf(params.get('flavour'))>-1)state.flavour=params.get('flavour');
  if(['featured','name','priced'].indexOf(params.get('sort'))>-1)state.sort=params.get('sort');
  if(['grid','list'].indexOf(params.get('view'))>-1)state.view=params.get('view');
  document.querySelectorAll('.swatch').forEach(function(btn){btn.addEventListener('click',function(){state.flavour=btn.dataset.flavour;applyState();});});
  document.querySelectorAll('.view-btn').forEach(function(btn){btn.addEventListener('click',function(){state.view=btn.dataset.view;applyState();});});
  var sort=document.getElementById('shop-sort');if(sort)sort.addEventListener('change',function(){state.sort=sort.value;applyState();});
  if(reset)reset.addEventListener('click',function(){state.flavour='all';state.sort='featured';state.view='grid';applyState();});
  applyState();
  var selectedFSetCurrent;
  if(selectedFRegular){
    var selectedFCatNav=document.querySelector('.sp-range-nav .sp-cats');
    if(selectedFCatNav){
      var selectedFLinks=Array.prototype.slice.call(selectedFCatNav.querySelectorAll('a'));
      var selectedFByTarget={};
      selectedFLinks.forEach(function(link){selectedFByTarget[link.getAttribute('href')]=link;});
      var selectedFAll=document.createElement('a');
      selectedFAll.href='#catalogue';
      selectedFAll.className='sp-all-products';
      selectedFAll.textContent='Shop all';
      selectedFCatNav.replaceChildren(selectedFAll);
      ['#bars','#moons','#bananas','#eclipses','#bites','#elixirs','#powder'].forEach(function(target){if(selectedFByTarget[target])selectedFCatNav.appendChild(selectedFByTarget[target]);});
      selectedFAll.addEventListener('click',function(){state.flavour='all';applyState();});
      selectedFLinks=Array.prototype.slice.call(selectedFCatNav.querySelectorAll('a'));
      selectedFSetCurrent=function(id){selectedFLinks.forEach(function(link){if(link.getAttribute('href')==='#'+id)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');});};
      var updateSelectedFCurrent=function(){
        var current=Array.prototype.slice.call(document.querySelectorAll('.sp-sec[id]')).filter(function(section){return !section.hidden;}).sort(function(a,b){return Math.abs(a.getBoundingClientRect().top-124)-Math.abs(b.getBoundingClientRect().top-124);})[0];
        if(current)selectedFSetCurrent(current.id);
      };
      selectedFLinks.forEach(function(link){link.addEventListener('click',function(){window.setTimeout(function(){selectedFSetCurrent(link.getAttribute('href').slice(1));},0);});});
      window.addEventListener('scroll',updateSelectedFCurrent,{passive:true});
      var selectedFRangeNav=selectedFCatNav.closest('.sp-range-nav');
      var updateSelectedFRailEdges=function(){
        var maxScroll=Math.max(0,selectedFCatNav.scrollWidth-selectedFCatNav.clientWidth);
        selectedFRangeNav.classList.toggle('is-scrollable',maxScroll>2);
        selectedFRangeNav.classList.toggle('is-at-start',selectedFCatNav.scrollLeft<=2);
        selectedFRangeNav.classList.toggle('is-at-end',selectedFCatNav.scrollLeft>=maxScroll-2);
      };
      var revealSelectedFLink=function(link){
        var padding=12;
        var maxScroll=Math.max(0,selectedFCatNav.scrollWidth-selectedFCatNav.clientWidth);
        var left=link.offsetLeft;
        var right=left+link.offsetWidth;
        var visibleLeft=selectedFCatNav.scrollLeft+padding;
        var visibleRight=selectedFCatNav.scrollLeft+selectedFCatNav.clientWidth-padding;
        if(left<visibleLeft)selectedFCatNav.scrollLeft=Math.max(0,left-padding);
        else if(right>visibleRight)selectedFCatNav.scrollLeft=Math.min(maxScroll,right-selectedFCatNav.clientWidth+padding);
        updateSelectedFRailEdges();
      };
      selectedFCatNav.addEventListener('scroll',updateSelectedFRailEdges,{passive:true});
      selectedFCatNav.addEventListener('focusin',function(event){if(event.target.matches('a'))revealSelectedFLink(event.target);});
      window.addEventListener('resize',updateSelectedFRailEdges);
      if('ResizeObserver' in window)new ResizeObserver(updateSelectedFRailEdges).observe(selectedFCatNav);
      if(document.readyState==='complete')updateSelectedFRailEdges();else window.addEventListener('load',updateSelectedFRailEdges,{once:true});
      window.setTimeout(updateSelectedFRailEdges,0);
    }
  }
  if(selectedFRegular&&window.location.hash){
    var initialAnchor=document.getElementById(window.location.hash.slice(1));
    var settleInitialAnchor=function(){if(initialAnchor&&window.location.hash.slice(1)===initialAnchor.id){var priorScrollBehavior=document.documentElement.style.scrollBehavior;document.documentElement.style.scrollBehavior='auto';window.scrollTo({top:Math.max(0,window.scrollY+initialAnchor.getBoundingClientRect().top-124),behavior:'auto'});document.documentElement.style.scrollBehavior=priorScrollBehavior;if(selectedFSetCurrent)selectedFSetCurrent(initialAnchor.id);}};
    var queueInitialAnchor=function(){window.setTimeout(settleInitialAnchor,450);};
    if(document.readyState==='complete')queueInitialAnchor();else window.addEventListener('load',queueInitialAnchor,{once:true});
  }

  var catLinks=Array.prototype.slice.call(document.querySelectorAll('.sp-range-nav .sp-cats a'));
  if('IntersectionObserver' in window){
    var setCurrent=function(id){
      catLinks.forEach(function(link){
        if(link.getAttribute('href')==='#'+id){link.setAttribute('aria-current','location');}
        else{link.removeAttribute('aria-current');}
      });
    };
    var sectionObserver=new IntersectionObserver(function(entries){
      var current=entries.filter(function(entry){return entry.isIntersecting;}).sort(function(a,b){return Math.abs(a.boundingClientRect.top)-Math.abs(b.boundingClientRect.top);})[0];
      if(current){setCurrent(current.target.id);}
    },{rootMargin:'-18% 0px -66% 0px',threshold:.01});
    document.querySelectorAll('.sp-sec[id], .sp-sampler[id], .sp-range-nav[id]').forEach(function(section){sectionObserver.observe(section);});
  }
})();


/* SHOP LANE: catalogue chapters stay navigable while purchase wiring remains pending. */
.sp .sp-range-nav{position:sticky;top:8px;z-index:4;padding:6px 0;background:transparent;border:0;}
.sp .sp-range-nav .sp-cats{position:static;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:0;width:min(880px,calc(100% - 56px));min-height:52px;margin:0 auto;padding:0;overflow:hidden;border:1px solid rgba(58,42,26,.10);border-radius:999px;background:rgba(238,248,249,.20);box-shadow:none;-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);}
.sp .sp-range-nav .sp-cats a{position:relative;display:flex;align-items:center;justify-content:center;min-height:52px;padding:8px 10px;border:0;border-left:1px solid rgba(58,42,26,.10);border-radius:0;background:transparent;color:rgba(44,42,38,.48);font-size:.6rem;letter-spacing:.08em;text-transform:uppercase;text-align:center;}
.sp .sp-range-nav .sp-cats a:first-child{border-left:0;}
.sp .sp-range-nav .sp-cats a[aria-current="location"]{color:var(--ink);font-weight:500;background:rgba(247,253,250,.50);box-shadow:none;}
.sp .sp-range-nav .sp-cats a[aria-current="location"]::after{content:"";position:absolute;bottom:10px;width:24px;height:2px;background:#9b8352;}
.sp .sp-range-nav .sp-cats a:hover{color:rgba(44,42,38,.82);background:rgba(247,253,250,.34);}
.sp .sp-range-nav .sp-cats.is-filtered{grid-template-columns:repeat(auto-fit,minmax(110px,1fr));}
.sp{--blue-flow:#b7c9d9;--blue-bridge:#c8d5df;--blue-haze:#d7e2ea;--blue-deep:#457798;--blue-night:#101923;--beige:#c9ba96;--acc:#4074b6;background:linear-gradient(180deg,var(--blue-flow) 0%,#c7d6e3 18%,var(--blue-haze) 44%,#e2e5df 70%,var(--paper) 100%);}
.sp-main{min-width:0;}
.sp-tools{display:grid;grid-template-columns:minmax(0,1fr) minmax(170px,220px) auto;gap:14px;align-items:center;margin:12px auto 10px;padding:16px 18px;border:1px solid rgba(69,119,152,.14);border-radius:8px;background:rgba(251,250,247,.68);box-shadow:0 8px 18px rgba(41,57,64,.045);}
.catalogue-toolbar-heading{grid-column:1/-1;display:flex;align-items:baseline;justify-content:space-between;gap:16px;padding-bottom:12px;border-bottom:1px solid rgba(69,119,152,.14);}
.catalogue-toolbar-heading h2{margin:0;font:500 1.04rem/1.2 var(--mm-serif);color:var(--ink);}
.reset-tool{min-height:36px;padding:6px 11px;border:0;border-bottom:1px solid currentColor;background:transparent;color:var(--ink-soft);font:500 .63rem/1 var(--mm-sans);letter-spacing:.12em;text-transform:uppercase;cursor:pointer;}
.reset-tool:hover{color:var(--ink);}
.tool-group{display:flex;align-items:center;gap:10px;min-width:0;color:rgba(44,42,38,.66);font-size:.62rem;letter-spacing:.13em;text-transform:uppercase;}
.flavour-tools{flex-wrap:wrap;}
.swatch,.view-btn{min-width:44px;min-height:44px;border:1px solid rgba(44,42,38,.14);border-radius:8px;background:rgba(255,255,255,.42);color:var(--ink);font:inherit;cursor:pointer;touch-action:manipulation;}
.swatch{position:relative;display:grid;place-items:center;padding:5px;}
.swatch i{display:block;width:24px;height:24px;border-radius:5px;background:var(--sw);border:1px solid rgba(44,42,38,.10);}
.swatch b{position:absolute;inline-size:1px;block-size:1px;overflow:hidden;clip-path:inset(50%);}
.swatch.is-active,.view-btn.is-active{border-color:var(--blue-night);box-shadow:inset 0 -2px 0 rgba(201,186,150,.62);background:rgba(255,255,255,.76);}
.sort-tool{justify-content:flex-end;}
.sort-tool select{min-height:44px;width:150px;padding:0 36px 0 14px;border:1px solid rgba(44,42,38,.16);border-radius:8px;background:rgba(255,255,255,.48);color:var(--ink);font:500 .78rem var(--mm-sans);}
.view-tools{justify-content:flex-end;}
.view-btn{padding:0 12px;font-size:.62rem;}
.catalogue-status{grid-column:1/-1;margin:0;padding-top:2px;color:var(--ink-soft);font-size:.78rem;line-height:1.35;}
.sp-tools :is(.swatch,.view-btn,.sort-tool select,.reset-tool):focus-visible{outline:2px solid var(--acc);outline-offset:3px;}
.sp-sec{scroll-margin-top:94px;padding:46px 0 10px;}
