/* SAT-SHOP-POLISH-R1 (render fix, 13 Aug): the block above declares
   max-height:78% on the compact-band product image, but a percentage does not
   resolve against a height derived from aspect-ratio, so the rule was inert.
   Tall portrait shots (elixirs, 1024x1536) rendered 235px inside a 198px panel
   and covered the product title by 88px at 1440. Anchoring the image box makes
   A's own 78% rule take effect. Design intent unchanged; square shots
   (bananas, powder) measured identically before and after. */
body.compact-variant-f .sp-compact-module .pcard .ph{position:relative;}
body.compact-variant-f .sp-compact-module .pcard .ph img,
body.compact-variant-f .sp-compact-bananas .pcard .ph img,
body.compact-variant-f .sp-compact-powder .pcard .ph img{
  position:absolute;
  inset:0;
  margin:auto;
  width:auto;
  height:78%;
  max-width:88%;
  max-height:78%;
  object-fit:contain;
}

/* SAT-SHOP-POLISH-R1 + selectors (13 Aug): moon pack / eclipse size controls.
   Sits between the description and the price row so the card's existing
   title -> chips -> copy -> price -> action hierarchy is unchanged. */
.pcard .price-wrap{display:flex;flex-direction:column;gap:3px;min-width:0;}
.pcard .sel-price{color:var(--ink-faint);font-size:.62rem;letter-spacing:.07em;text-transform:uppercase;line-height:1.25;}
.size-picker{display:flex;align-items:center;justify-content:space-between;gap:10px;min-width:0;margin-top:2px;padding:8px 0 0;border-top:1px solid rgba(44,42,38,.09);color:var(--ink-soft);font-size:.58rem;letter-spacing:.1em;text-transform:uppercase;}
.size-picker>span{flex:0 0 auto;}
.size-picker.is-made-to-order{justify-content:space-between;}
.size-picker .mto{flex:0 0 auto;font-style:normal;opacity:.72;letter-spacing:.06em;text-transform:none;font-size:.72rem;}
.size-select{flex:0 1 auto;min-width:0;min-height:34px;max-width:100%;padding:0 26px 0 9px;border:0;border-bottom:1px solid rgba(44,42,38,.24);border-radius:0;background:transparent;color:var(--ink);font:500 .72rem var(--mm-sans);}
.sp-tools :is(.swatch,.view-btn,.sort-tool select,.reset-tool):focus-visible,
.size-select:focus-visible{outline:2px solid var(--acc);outline-offset:3px;}
body.compact-variant-f .size-picker{padding-top:7px;font-size:.56rem;}
body.compact-variant-f .size-select{min-height:34px;font-size:.7rem;}
body.compact-variant-f .sp-compact-module .size-picker{margin-top:auto;}
@media(max-width:560px){
  .pcard .row{align-items:stretch;}
  .size-picker{flex-wrap:wrap;gap:6px;}
  .size-select{width:100%;max-width:100%;}
}



