/* Category dock. It is a FIXED N-column grid (repeat(8,minmax(0,1fr))) inside a track of
   min(930px, 100% - 48px). At 390 that is ~43px per column against labels like "SHOP ALL"
   and "BANANAS", so every label clipped mid-word and the row read as broken. It already
   hides its own scrollbar, so scrolling was always the intent. Let each item take its
   natural width and snap. Verified pre-existing: the same clipping is present in the
   pre-change backup, so this is not a regression from restoring #eclipses. */
@media(max-width:760px){
  .sp-range-nav .sp-cats,
  body.compact-variant-f .sp-range-nav .sp-cats{
    grid-template-columns:none!important;
    grid-auto-flow:column;
    grid-auto-columns:max-content;
    overflow-x:auto;
    -webkit-overflow-scrolling:touch;
    scroll-snap-type:x proximity;
    scroll-padding-left:12px;
  }
  .sp-range-nav .sp-cats>*{scroll-snap-align:start;padding-left:18px;padding-right:18px;
    white-space:nowrap;}
}
